<span class="line"><span style="color:#C678DD;">    if</span><span style="color:#ABB2BF;"> ! </span><span style="color:#61AFEF;">docker</span><span style="color:#98C379;"> info</span><span style="color:#ABB2BF;"> &gt;</span><span style="color:#98C379;">/dev/null</span><span style="color:#ABB2BF;"> 2&gt;&amp;1; </span><span style="color:#C678DD;">then</span></span>
